    /** Inline SVG for a sport name as venues store it ("Cricket", "Cricket Nets", "Box cricket"). */
    public static function svg(string $sport, int $size = 18): string
    {
        $d = self::PATHS[self::key($sport)];

        return '<svg class="sport-tab__icon" viewBox="0 0 24 24" width="' . $size . '" height="' . $size
            . '" fill="currentColor" aria-hidden="true" focusable="false"><path d="' . $d . '"/></svg>';
    }

    private static function key(string $sport): string
    {
        $s = strtolower($sport);

        return match (true) {
            str_contains($s, 'cricket') => 'cricket',
            str_contains($s, 'football'), str_contains($s, 'soccer'), str_contains($s, 'futsal') => 'football',
            str_contains($s, 'basket') => 'basketball',
            str_contains($s, 'volley') => 'volleyball',
            str_contains($s, 'pickle') => 'pickleball',
            str_contains($s, 'badminton'), str_contains($s, 'shuttle') => 'badminton',
            str_contains($s, 'tennis') => 'tennis',
            default => 'other',
        };
    }
}
